    status: str | None = None,
    milestone: str | None = None,
    team_leader: uuid.UUID | None = None,
) -> ProjectListResponse:
    items, total, page, page_size = list_projects_service(
        db,
        page=page,
        page_size=page_size,
        q=q,
        status=status,
        milestone=milestone,
        team_leader=team_leader,
    )

    result = []
    for p in items:
        item = ProjectRead.model_validate(p)
        result.append(item)

    return ProjectListResponse(
        items=result,
        total=total,
        page=page,
        page_size=page_size,
